// Ready for document generation = validated by WF1 AND no PdfUrl yet.
// This is what prevents re-generating the same document every minute.
const pending = $input.all().filter(i => {
  const status = (i.json.Status || '');
  const url = (i.json.PdfUrl || '');
  return status === 'Validated' && !url;
});

// Empty DB / nothing pending -> [] -> workflow ends quietly.
return pending;

// Build a Hebrew RTL invoice document (HTML) for each pending invoice.
const results = [];
const fmt = (n) => Number(n ?? 0).toLocaleString('he-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

for (const item of $input.all()) {
  const inv = item.json;

  // Format Created as dd/mm/yyyy
  let createdStr = '';
  if (inv.Created) {
    const d = new Date(inv.Created);
    if (!isNaN(d.getTime())) {
      const dd = String(d.getDate()).padStart(2, '0');
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      createdStr = `${dd}/${mm}/${d.getFullYear()}`;
    }
  }

  const html = `<!DOCTYPE html>
<html lang='he' dir='rtl'>
<head>
<meta charset='UTF-8'>
<title>חשבונית ${inv.InvoiceNumber ?? ''}</title>
<style>
body{font-family:Arial,Helvetica,sans-serif;direction:rtl;background:#f4f4f4;margin:0;padding:24px;color:#222;}
.invoice{max-width:700px;margin:0 auto;background:#fff;border:1px solid #ddd;border-radius:8px;padding:32px;}
h1{margin:0 0 4px;font-size:24px;}
.sub{color:#666;margin-bottom:24px;}
table{width:100%;border-collapse:collapse;margin-top:16px;}
th,td{border:1px solid #e0e0e0;padding:10px;text-align:right;}
th{background:#fafafa;}
.totals td{border:none;padding:6px 10px;}
.label{color:#555;}
.total-row{font-weight:bold;font-size:18px;border-top:2px solid #333;}
.footer{margin-top:28px;color:#888;font-size:12px;text-align:center;}
</style>
</head>
<body>
<div class='invoice'>
<h1>חשבונית מס</h1>
<div class='sub'>מספר חשבונית: ${inv.InvoiceNumber ?? ''}</div>
<table>
<tr><th>שדה</th><th>פרט</th></tr>
<tr><td>מספר חשבונית</td><td>${inv.InvoiceNumber ?? ''}</td></tr>
<tr><td>מזהה לקוח</td><td>${inv.CustomerId ?? ''}</td></tr>
<tr><td>תאריך</td><td>${createdStr}</td></tr>
</table>
<table class='totals'>
<tr><td class='label'>סכום לפני מע״מ</td><td>${fmt(inv.Amount)} ₪</td></tr>
<tr><td class='label'>מע״מ (18%)</td><td>${fmt(inv.VatAmount)} ₪</td></tr>
<tr class='total-row'><td>סה״כ לתשלום</td><td>${fmt(inv.Total)} ₪</td></tr>
</table>
<div class='footer'>מסמך זה הופק אוטומטית על ידי מערכת ה-ERP.</div>
</div>
</body>
</html>`;

  const filename = `invoice-${inv.InvoiceNumber || inv.id}.html`;
  results.push({ json: { id: inv.id, InvoiceNumber: inv.InvoiceNumber, filename, html } });
}

return results;
